{
  "name": "Eurotherm 2408 温度过程控制器",
  "name_en": "Eurotherm 2408 Process Temperature Controller",
  "manufacturer": "Eurotherm",
  "description": "Eurotherm 2408 是一款面板安装式温度/过程控制器，用于实验室和工业加热系统的温度调节。它可读取温度传感器信号，并通过设定值、PID 参数、斜坡速率、手动/自动模式和功率输出等功能对炉体、加热器或工艺过程进行闭环控制。",
  "description_en": "The Eurotherm 2408 is a panel-mounted temperature/process controller used to regulate heating systems in laboratories and industrial setups. It reads temperature sensor signals and provides closed-loop control of furnaces, heaters, or thermal processes through setpoint control, PID tuning, ramp rate settings, manual/automatic modes, and power output adjustment.",
  "tag_hints": [
    "temperature control",
    "process controller",
    "PID control",
    "furnace heating",
    "setpoint ramping",
    "panel-mounted controller",
    "sensor input"
  ],
  "actions": [
    {
      "action_name": "auto-reconnect",
      "description": "重新连接控制器通信",
      "description_en": "reconnect communication with the controller"
    },
    {
      "action_name": "auto-dumpAll",
      "description": "读取并导出全部可用参数/状态",
      "description_en": "read and dump all available parameters/status values"
    },
    {
      "action_name": "auto-setpoint",
      "description": "获取/设置设定值",
      "description_en": "get/set setpoint"
    },
    {
      "action_name": "auto-P",
      "description": "获取/设置比例增益 P",
      "description_en": "get/set proportional gain P"
    },
    {
      "action_name": "auto-I",
      "description": "获取/设置积分时间 I",
      "description_en": "get/set integral time I"
    },
    {
      "action_name": "auto-D",
      "description": "获取/设置微分时间 D",
      "description_en": "get/set derivative time D"
    },
    {
      "action_name": "auto-P2",
      "description": "获取/设置第二组比例增益 P2",
      "description_en": "get/set second proportional gain P2"
    },
    {
      "action_name": "auto-I2",
      "description": "获取/设置第二组积分时间 I2",
      "description_en": "get/set second integral time I2"
    },
    {
      "action_name": "auto-D2",
      "description": "获取/设置第二组微分时间 D2",
      "description_en": "get/set second derivative time D2"
    },
    {
      "action_name": "auto-power",
      "description": "获取/设置功率输出",
      "description_en": "get/set power output"
    },
    {
      "action_name": "auto-manual",
      "description": "获取/设置手动模式",
      "description_en": "get/set manual mode"
    },
    {
      "action_name": "auto-pid",
      "description": "获取/设置第一组 PID 参数",
      "description_en": "get/set first PID parameter set"
    },
    {
      "action_name": "auto-pid2",
      "description": "获取/设置第二组 PID 参数",
      "description_en": "get/set second PID parameter set"
    },
    {
      "action_name": "auto-cutbackHigh",
      "description": "获取/设置高切回值",
      "description_en": "get/set high cutback value"
    },
    {
      "action_name": "auto-cutbackLow",
      "description": "获取/设置低切回值",
      "description_en": "get/set low cutback value"
    },
    {
      "action_name": "auto-automatic",
      "description": "获取/设置自动模式",
      "description_en": "get/set automatic mode"
    },
    {
      "action_name": "auto-rampRate",
      "description": "获取/设置设定值斜坡速率",
      "description_en": "get/set setpoint ramp rate"
    },
    {
      "action_name": "auto-temperatureSensor",
      "description": "获取/设置温度传感器类型",
      "description_en": "get/set temperature sensor type"
    },
    {
      "action_name": "auto-rampUnit",
      "description": "获取/设置斜坡单位",
      "description_en": "get/set ramp unit"
    },
    {
      "action_name": "auto-timeUnits",
      "description": "获取/设置时间单位",
      "description_en": "get/set time units"
    },
    {
      "action_name": "auto-tensionRange",
      "description": "获取/设置电压范围",
      "description_en": "get/set voltage range"
    },
    {
      "action_name": "auto-decimalsDisp",
      "description": "获取/设置显示小数位数",
      "description_en": "get/set displayed decimal places"
    }
  ]
}

